    'entry/src/main/ets/MainAbility/pages/onScrollIndex/onScrollIndexFlow1.ets',
    'entry/src/main/ets/MainAbility/pages/onScrollIndex/onScrollIndexFlow2.ets',
    'entry/src/main/ets/MainAbility/pages/onScrollIndex/onScrollIndexFlow3.ets'
  ].map(file => path.join(root, file));
